import csv
import sqlite3
import os

def process_upload(tmp_path, db_path):
    try:
        with sqlite3.connect(db_path) as conn:
            cursor = conn.cursor()
            with open(tmp_path, 'r') as file:
                reader = csv.reader(file)
                for row in reader:
                    cursor.execute('INSERT INTO events VALUES (?, ?)', row)
            conn.commit()
    except Exception as e:
        try:
            with sqlite3.connect(db_path) as conn:
                conn.rollback()
        except sqlite3.Error:
            pass
        raise e
    finally:
        try:
            os.remove(tmp_path)
        except OSError:
            pass
