    sales_df['amount'] = pd.to_numeric(sales_df['amount'].str.replace('.', '', regex=False))
    region_totals_df = sales_df.groupby('region')['amount'].sum().reset_index()
    return region_totals_df

# Write region totals to region_totals.csv
def write_region_totals_csv(region_totals_df, file_name):
    try:
        region_totals_df.to_csv(file_name, index=False)
    except Exception as e:
        print(f"Error writing to file {file_name}: {str(e)}")

# Main function
def main():
    sales_df = read_sales_csv('sales.csv')
    if sales_df is not None:
        region_totals_df = calculate_region_totals(sales_df)
        write_region_totals_csv(region_totals_df, 'region_totals.csv')

if __name__ == "__main__":
