# test_pricing.py
import pytest
from pricing import weekend_discount


class _FakeDate:
    """Helper to fake datetime.now().weekday()"""

    def __init__(self, weekday: int):
        self._weekday = weekday

    @staticmethod
    def now():
        """Will be replaced by a lambda that returns an instance with the desired weekday."""
        raise NotImplementedError


def _make_fake_datetime(weekday: int):
    """Create a fake datetime class whose now() returns an object with the given weekday."""
    class _NowResult:
        @staticmethod
        def weekday() -> int:
            return weekday

    class _FakeDatetime:
        @staticmethod
        def now() -> _NowResult:
            return _NowResult()

    return _FakeDatetime


def test_weekend_discount_applies(monkeypatch):
    """When today is Saturday (weekday 5) the discount should be applied."""
    monkeypatch.setattr("pricing.datetime", _make_fake_datetime(5))
    assert weekend_discount(100) == 90.0
    # also test rounding behavior
    assert weekend_discount(123.456) == round(123.456 * 0.9, 2)


def test_weekend_discount_not_applied(monkeypatch):
    """When today is a weekday (e.g., Wednesday, weekday 2) the price should stay unchanged."""
    monkeypatch.setattr("pricing.datetime", _make_fake_datetime(2))
    price = 99.99
    assert weekend_discount(price) == price
